/* Portable planners: money uses integer minor units; dates use local calendar days. */
(function(root){'use strict';
const currencies=['USD','CAD','EUR','GBP','AUD','NZD','INR'];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const localDate=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');
function validDate(s){if(typeof s!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(s)||s<'1900-01-01'||s>'2199-12-31')return false;const d=new Date(s+'T12:00:00');return Number.isFinite(+d)&&localDate(d)===s;}
const validMonth=s=>typeof s==='string'&&/^\d{4}-\d{2}$/.test(s)&&validDate(s+'-01');
function shiftDate(s,days){if(!validDate(s))throw Error('Choose a valid date.');const d=new Date(s+'T12:00:00');d.setDate(d.getDate()+days);const result=localDate(d);return validDate(result)?result:null;}
function shiftMonth(s,delta){if(!validMonth(s))throw Error('Choose a valid month.');const d=new Date(s+'-01T12:00:00');d.setMonth(d.getMonth()+delta);const result=localDate(d).slice(0,7);return validMonth(result)?result:null;}
function monthDays(month){if(!validMonth(month))throw Error('Choose a valid month.');const first=new Date(month+'-01T12:00:00'),start=new Date(first);start.setDate(1-first.getDay());return Array.from({length:42},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);return localDate(d);});}
function amount(value){if(typeof value!=='string'||value.length>24)throw Error('Enter an amount.');value=value.trim();if(!value)return 0;if(!/^\d{1,9}(?:\.\d{1,2})?$/.test(value))throw Error('Use a positive amount with up to two decimal places.');const [whole,part='']=value.split('.');return Number(whole)*100+Number(part.padEnd(2,'0'));}
function money(cents,currency){return new Intl.NumberFormat(undefined,{style:'currency',currency,maximumFractionDigits:2}).format(cents/100);}
function budget(uid,date=localDate(new Date())){return {month:date.slice(0,7),currency:'USD',reserve:'',rows:[['income','Income'],['expense','Essentials'],['expense','Something to look forward to']].map(([kind,label])=>({id:uid(),kind,label,planned:'',actual:''}))};}
function budgetTotals(plan){const totals={plannedIncome:0,actualIncome:0,plannedExpense:0,actualExpense:0,reserve:0,errors:[]};for(const row of plan.rows)for(const key of ['planned','actual']){try{totals[key+(row.kind==='income'?'Income':'Expense')]+=amount(row[key]);}catch(e){totals.errors.push({id:row.id,field:key,message:e.message});}}try{totals.reserve=amount(plan.reserve);}catch(e){totals.errors.push({id:'reserve',field:'reserve',message:e.message});}totals.plannedLeft=totals.plannedIncome-totals.plannedExpense-totals.reserve;totals.actualLeft=totals.actualIncome-totals.actualExpense-totals.reserve;return totals;}
function budgetHTML(plan){const t=budgetTotals(plan),show=value=>{try{return money(amount(value),plan.currency);}catch{return 'Check amount: '+value;}};return `<p>${esc(plan.month)} · ${plan.currency}</p><p>Set aside: ${esc(show(plan.reserve))}</p>`+plan.rows.map(r=>`<h2>${esc(r.label||'Untitled category')} · ${r.kind}</h2><p>Planned: ${esc(show(r.planned))} · Actual: ${esc(show(r.actual))}</p>`).join('')+(t.errors.length?'<p>Finish the highlighted amounts before using totals.</p>':`<h2>Room to spend</h2><p>Planned: ${esc(money(t.plannedLeft,plan.currency))} · Actual: ${esc(money(t.actualLeft,plan.currency))}</p>`);}
function calendar(date=localDate(new Date())){if(!validDate(date))throw Error('Choose a date between 1900 and 2199.');return {month:date.slice(0,7),selected:date,events:[]};}
function dayEntries(cal,date){return cal.events.filter(e=>e.date===date).sort((a,b)=>(a.time||'00:00').localeCompare(b.time||'00:00')||a.title.localeCompare(b.title));}
function calendarHTML(cal){return [...cal.events].sort((a,b)=>(a.date+(a.time||'')).localeCompare(b.date+(b.time||''))).map(e=>`<h2>${esc(e.date)} · ${esc(e.time||'All day')} · ${esc(e.title||'Untitled plan')}</h2><p>${esc(e.body).replace(/\n/g,'<br>')}</p>`).join('')||'<p>A calendar with room for plans, thoughts, and small next steps.</p>';}
function validateNote(n){const text=(v,max)=>typeof v==='string'&&v.length<=max,id=v=>text(v,100)&&/^[-A-Za-z0-9_]+$/.test(v);if(n.budget){const b=n.budget;if(!validMonth(b.month)||!currencies.includes(b.currency)||!text(b.reserve,24)||!Array.isArray(b.rows)||b.rows.length<1||b.rows.length>80)throw Error('Invalid budget planner');const ids=new Set();for(const r of b.rows){if(!r||!id(r.id)||ids.has(r.id)||!['income','expense'].includes(r.kind)||!text(r.label,100)||!text(r.planned,24)||!text(r.actual,24))throw Error('Invalid budget category');ids.add(r.id);}}
 if(n.calendar){const c=n.calendar;if(c.cardView!==undefined&&!['agenda','month'].includes(c.cardView))throw Error('Invalid calendar card view');if(!validMonth(c.month)||!validDate(c.selected)||c.selected.slice(0,7)!==c.month||!Array.isArray(c.events)||c.events.length>300)throw Error('Invalid calendar');const ids=new Set();for(const e of c.events){if(!e||!id(e.id)||ids.has(e.id)||!validDate(e.date)||!text(e.title,160)||!text(e.body,4000)||typeof e.time!=='string'||e.time!==''&&!/^(?:[01]\d|2[0-3]):[0-5]\d$/.test(e.time)||e.taskId!==undefined&&!id(e.taskId)||e.sourceItemId!==undefined&&!id(e.sourceItemId)||e.sourceKey!==undefined&&!text(e.sourceKey,100))throw Error('Invalid calendar entry');ids.add(e.id);}}
 for(const [mode,key]of [['budget','budget'],['calendar','calendar']])if(n.inputMode===mode&&(n.type!=='note'||!n[key]))throw Error('Missing planner data');return n;}
const api={currencies,validDate,validMonth,localDate,shiftDate,shiftMonth,monthDays,amount,money,budget,budgetTotals,budgetHTML,calendar,dayEntries,calendarHTML,validateNote};if(typeof module!=='undefined')module.exports=api;else root.NotaPlanning=api;
})(typeof window!=='undefined'?window:globalThis);
